#!/usr/bin/env python3
import os
import sys

def generate_header():
    base_dir = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    html_path = os.path.join(base_dir, "web", "index.html")
    header_path = os.path.join(base_dir, "include", "web_index_html.h")

    if not os.path.exists(html_path):
        print(f"Error: {html_path} does not exist!", file=sys.stderr)
        sys.exit(1)

    with open(html_path, "r", encoding="utf-8") as f:
        html_content = f.read()

    header_content = f"""// Auto-generated from web/index.html by scripts/embed_web.py
// DO NOT EDIT THIS FILE DIRECTLY. Edit web/index.html instead.
#pragma once
#include <Arduino.h>

const char INDEX_HTML[] PROGMEM = R"rawliteral({html_content})rawliteral";
"""

    os.makedirs(os.path.dirname(header_path), exist_ok=True)
    with open(header_path, "w", encoding="utf-8") as f:
        f.write(header_content)

    print(f"[embed_web] Successfully generated {header_path} from {html_path} ({len(html_content)} bytes)")

# PlatformIO hook compatibility
try:
    from SCons.Script import Import
    Import("env")
    generate_header()
except Exception:
    # Run as standalone python script
    if __name__ == "__main__":
        generate_header()
